import{fork}from'node:child_process';import{once}from'node:events';import{mkdtempSync,rmSync,writeFileSync,readFileSync}from'node:fs';import{tmpdir}from'node:os';import{join,resolve}from'node:path';import{createHash}from'node:crypto';import assert from'node:assert/strict';import prettier from'prettier';import{Tracer}from'../../src/index.ts';import{SQLiteRepository}from'../../src/persistence/sqlite.ts';
const actor={actor:'native-process-proof'},schema={entityTypes:{item:{fields:{title:{type:'string'}}}},relationshipTypes:{connects:{fields:{}}}},results=[];
function wait(child,predicate){return new Promise((resolve,reject)=>{const timer=setTimeout(()=>{child.off('message',listener);reject(Error('worker timeout'));},10000);const listener=m=>{if(predicate(m)){clearTimeout(timer);child.off('message',listener);resolve(m);}};child.on('message',listener);});}
async function run(name,prepare,verify){const dir=mkdtempSync(join(tmpdir(),'tracer-native-race-')),database=join(dir,'project.sqlite'),r=new SQLiteRepository(database),t=new Tracer(r),children=[];try{await t.setSchema(schema,0,actor);const proposals=await prepare(t),before=await t.exportProject();for(let i=0;i<2;i++){const child=fork(resolve('output/concurrent-local/workload-worker.mjs'),[database],{stdio:['ignore','ignore','inherit','ipc']});children.push(child);await wait(child,m=>m.ready);}const outcomes=await Promise.all(children.map((child,i)=>{const result=wait(child,m=>m.id===1);child.send({id:1,...proposals[i]});return result;}));const after=await t.exportProject();await verify(t,outcomes,before,after);for(const link of after.current.relationships){assert.ok(after.current.entities.some(e=>e.id===link.source));assert.ok(after.current.entities.some(e=>e.id===link.target));}results.push({name,proposals,outcomes:outcomes.map(o=>({error:o.error??null,durationMs:o.durationMs??null,result:o.result??null})),nativeBefore:before.projectRevision,nativeAfter:after.projectRevision,receiptDelta:after.evidence.receipts.length-before.evidence.receipts.length,activeEndpointsValid:true});}finally{for(const child of children){const exited=once(child,'exit');child.kill();await exited;}r.close();rmSync(dir,{recursive:true,force:true});}}
const apply=(commandId,operations)=>({method:'applyChangeset',args:[{commandId,expectedSchemaVersion:1,operations,provenance:actor}]});
const oneWinner=(outcomes)=>{assert.equal(outcomes.filter(x=>!x.error).length,1);for(const o of outcomes)if(o.error)assert.ok(['busy','conflict','not_found','referential_integrity','schema_conflict','validation'].includes(o.error.code));};
await run('same-native-version',async t=>{const entity=await t.createEntity({type:'item',fields:{}},1,actor);return['A','B'].map(value=>apply('update-'+value,[{op:'entity.update',id:entity.id,expectedVersion:1,input:{fields:{title:value}}}]));},async(t,outcomes,before,after)=>{oneWinner(outcomes);assert.equal(after.projectRevision,before.projectRevision+1);const e=after.current.entities[0];assert.equal(e.version,2);assert.deepEqual((await t.history({id:e.id})).items.map(x=>x.version),[1,2]);});
await run('canonical-resource-identity',async()=>['A','B'].map(value=>apply('resource-'+value,[{op:'entity.create',input:{type:'@resource',fields:{},resource:{label:value,source:{system:'file',externalId:'same-external-identity'}}}}])),async(t,outcomes,before,after)=>{oneWinner(outcomes);assert.equal(after.current.entities.length,1);const e=after.current.entities[0];await t.removeEntity(e.id,e.version,1,actor);await assert.rejects(t.applyChangeset({commandId:'reassign-deleted-resource',expectedSchemaVersion:1,operations:[{op:'entity.create',input:{type:'@resource',fields:{},resource:{label:'reassignment',source:{system:'file',externalId:'same-external-identity'}}}}]},actor),{code:'conflict'});assert.equal(await t.getChangesetOutcome('reassign-deleted-resource'),null);});
await run('endpoint-deletion-versus-link',async t=>{const a=await t.createEntity({type:'item',fields:{}},1,actor),b=await t.createEntity({type:'item',fields:{}},1,actor);return[apply('delete-endpoint',[{op:'entity.remove',id:b.id,expectedVersion:1}]),apply('connect-endpoint',[{op:'relationship.create',input:{type:'connects',source:a.id,target:b.id,fields:{}},expectedEndpoints:{sourceVersion:1,targetVersion:1}}])];},async(t,outcomes,before,after)=>{oneWinner(outcomes);assert.equal(after.projectRevision,before.projectRevision+1);for(const [index,outcome]of outcomes.entries())if(outcome.error)assert.equal(await t.getChangesetOutcome(index?'connect-endpoint':'delete-endpoint'),null);});
await run('schema-versus-data',async()=>[{method:'setSchema',args:[{entityTypes:{item:{fields:{title:{type:'number'}}}},relationshipTypes:{connects:{fields:{}}}},1,actor]},apply('string-under-old-schema',[{op:'entity.create',input:{type:'item',fields:{title:'string'}}}])],async(t,outcomes,before,after)=>{oneWinner(outcomes);assert.equal(after.projectRevision,before.projectRevision+1);if(after.current.schema.version===2)assert.equal(after.current.entities.length,0);else assert.equal(after.current.entities[0].fields.title,'string');});
await run('identical-native-plus-receipt-identity',async t=>{const input=await t.createEntity({type:'item',fields:{title:'criterion'}},1,actor),outputId=crypto.randomUUID(),command={commandId:'same-evaluation',expectedSchemaVersion:1,operations:[{op:'entity.create',id:outputId,input:{type:'item',fields:{title:'output'}}}],receipt:{outputId,expectedOutputVersion:1,outcome:'Synthetic identity-race proof',inputs:[{entityId:input.id}]}};return[0,1].map(()=>({method:'evaluations.commit',args:[command,actor]}));},async(t,outcomes,before,after)=>{const successes=outcomes.filter(x=>!x.error);assert.ok(successes.length>=1);for(const o of outcomes){if(o.error)assert.equal(o.error.code,'busy');else assert.deepEqual(o.result,successes[0].result);}assert.equal(after.projectRevision,before.projectRevision+1);assert.equal(after.evidence.receipts.length-before.evidence.receipts.length,1);assert.deepEqual(await t.evaluations.getOutcome('same-evaluation'),successes[0].result);});
await run('relink-versus-cascading-endpoint-deletion',async t=>{const a=await t.createEntity({type:'item',fields:{}},1,actor),b=await t.createEntity({type:'item',fields:{}},1,actor),c=await t.createEntity({type:'item',fields:{}},1,actor),link=await t.createRelationship({type:'connects',source:a.id,target:b.id,fields:{}},1,actor);return[apply('relink-to-survivor',[{op:'relationship.update',id:link.id,expectedVersion:1,input:{type:'connects',source:a.id,target:c.id,fields:{}}}]),apply('cascade-old-target',[{op:'entity.remove',id:b.id,expectedVersion:1,cascade:true}])];},async(t,outcomes,before,after)=>{const successes=outcomes.filter(x=>!x.error);assert.ok(successes.length>=1);assert.equal(after.projectRevision,before.projectRevision+successes.length);for(const o of outcomes)if(o.error)assert.ok(['busy','not_found','conflict'].includes(o.error.code));const original=before.current.relationships[0],history=(await t.history({id:original.id})).items;assert.equal(history.length,2);assert.deepEqual(history.map(x=>x.version),[1,2]);for(const [index,o]of outcomes.entries())if(!o.error)assert.deepEqual(await t.getChangesetOutcome(index?'cascade-old-target':'relink-to-survivor'),o.result);});
const report={date:'2026-10-28',scope:'Two independent OS processes per disposable minimal public-command fixture. Simultaneous guarded operation requests; exact outcomes and final committed invariants retained.',workerSha256:createHash('sha256').update(readFileSync('output/concurrent-local/workload-worker.mjs')).digest('hex'),results,limitations:'One run per scenario; no instrumented held-lock overlap within these application requests. Existing committed process tests separately hold transactions to establish lock/snapshot overlap. Controlled changed-basis/result-selection races and authenticated backend semantics are not established by these cases.'};writeFileSync('projects/tracer/concurrent-local-native-races-expanded.json',await prettier.format(JSON.stringify(report),{...await prettier.resolveConfig('projects/tracer/concurrent-local-native-races-expanded.json'),parser:'json'}),{flag:'wx'});console.log(JSON.stringify(results.map(r=>({name:r.name,outcomes:r.outcomes.map(x=>x.error?.code??'success')}))));

