function wait(child,predicate){return new Promise((resolve,reject)=>{const timer=setTimeout(()=>{child.off('message',listener);reject(Error('worker timeout'));},10000);const listener=m=>{if(predicate(m)){clearTimeout(timer);child.off('message',listener);resolve(m);}};child.on('message',listener);});}
async function workers(database){const children=[];for(let i=0;i<2;i++){const child=fork(resolve('output/concurrent-local/workload-worker.mjs'),[database],{stdio:['ignore','ignore','inherit','ipc']});await wait(child,m=>m.ready);children.push(child);}let id=0;return{request(index,method,...args){const selected=++id,promise=wait(children[index],m=>m.id===selected);children[index].send({id:selected,method,args});return promise;},async close(){for(const child of children){const exited=once(child,'exit');child.kill();await exited;}}};}
async function assertRace(t,responses,inputs,before){const successes=responses.filter(r=>!r.error);assert.equal(successes.length,1,JSON.stringify(responses));for(const [index,response]of responses.entries()){if(response.error){assert.ok(['conflict','busy'].includes(response.error.code));assert.equal(await t.evaluations.getOutcome(inputs[index].commandId),null);}else assert.deepEqual(await t.evaluations.getOutcome(inputs[index].commandId),response.result);}const after=await t.exportProject();assert.equal(after.projectRevision,before.projectRevision+1);assert.equal(after.evidence.receipts.length,before.evidence.receipts.length+1);for(const key of['changesets','revisions'])assert.deepEqual(after.provenance[key].slice(0,before.provenance[key].length),before.provenance[key]);return{outcomes:responses.map(r=>r.error?.code??'success'),nativeBefore:before.projectRevision,nativeAfter:after.projectRevision,receiptDelta:1};}
const results=[];
for(const domain of['engineering','research']){
 const f=await verificationFixture(domain);let w;try{const opening=await verificationOpening(f);await f.tracer.verification.open(opening,verificationActor);const selection={caseId:opening.caseId,openingCommandId:opening.commandId};w=await workers(f.database);const inputs=await Promise.all([verificationExecution(f,selection),verificationExecution(f,selection)]),before=await f.tracer.exportProject(),responses=await Promise.all(inputs.map((input,i)=>w.request(i,'verification.recordExecution',input,verificationActor))),capture=await assertRace(f.tracer,responses,inputs,before),winner=responses.findIndex(x=>!x.error),first=inputs[winner];assert.equal((await f.tracer.verification.get(selection)).executions.length,1);
 const select=await verificationResults(f,selection,first.executionId),next=await verificationExecution(f,selection),beforeSelection=await f.tracer.exportProject(),choices=await Promise.all([w.request(0,'verification.selectResults',select,verificationActor),w.request(1,'verification.recordExecution',next,verificationActor)]),selectionRace=await assertRace(f.tracer,choices,[select,next],beforeSelection);
 const stale=await verificationExecution(f,selection),requirement=await f.tracer.getEntity(f.requirement.id),field=f.definition.requirement.fields.acceptance[0],changed=await w.request(1,'applyChangeset',{commandId:`${domain}-changed-requirement`,expectedSchemaVersion:1,operations:[{op:'entity.update',id:requirement.id,expectedVersion:requirement.version,input:{fields:{...requirement.fields,[field]:requirement.fields[field]+' Revised acceptance.'}}}],provenance:verificationActor});assert.equal(changed.error,undefined);const rejected=await w.request(0,'verification.recordExecution',stale,verificationActor);assert.equal(rejected.error.code,'conflict');assert.equal(await f.tracer.evaluations.getOutcome(stale.commandId),null);const analysis=await f.tracer.verification.analyze(selection);assert.equal(analysis.basis.state,'changed');assert.notEqual(analysis.completion.state,'verified');assert.equal((await f.tracer.verification.execution(selection,first.executionId)).data.results[0].outcome,'passed');results.push({domain,capability:'verification',inputs,capture,selectionInputs:[select,next],selectionRace,changedBasis:{rejectedCode:rejected.error.code,noOutcome:true,basis:analysis.basis,completion:analysis.completion,originalTypedOutcomeRetained:true},limits:'Synthetic typed attestations test lifecycle semantics; no physical/scientific validity claim.'});
 }finally{await w?.close();f.close();}
 const a=await applicationModelFixture(domain);w=undefined;try{const opening=await assessmentOpenRequest(a);await a.tracer.changeAssessments.open(opening,evaluationActor);const selection={assessmentId:opening.assessmentId,openingCommandId:opening.commandId},subject={kind:'entity',id:a.criterion.id},initial=await dispositionProposal(a,selection,subject);initial.decision='investigate';initial.actions=[{id:'retained-action',kind:'investigate',title:'Resolve declared synthetic question',state:'open',resolution:'',support:[]}];await a.tracer.changeAssessments.setDisposition(initial,evaluationActor);w=await workers(a.database);const inputs=await Promise.all([dispositionProposal(a,selection,subject),dispositionProposal(a,selection,subject)]);inputs.forEach((input,i)=>{input.rationale='Independent proposed judgment '+i;input.decision='investigate';});const before=await a.tracer.exportProject(),responses=await Promise.all(inputs.map((input,i)=>w.request(i,'changeAssessments.setDisposition',input,evaluationActor))),disposition=await assertRace(a.tracer,responses,inputs,before);assert.equal((await a.tracer.changeAssessments.disposition(selection,subject)).actions[0].id,'retained-action');
 const stale=await dispositionProposal(a,selection,subject);stale.decision='investigate';const criterion=await a.tracer.getEntity(a.criterion.id),changed=await w.request(1,'applyChangeset',{commandId:`${domain}-changed-assessment-basis`,expectedSchemaVersion:2,operations:[{op:'entity.update',id:criterion.id,expectedVersion:criterion.version,input:{fields:{...criterion.fields,[a.model.threshold]:a.model.value+1}}}],provenance:evaluationActor});assert.equal(changed.error,undefined);const rejected=await w.request(0,'changeAssessments.setDisposition',stale,evaluationActor);assert.equal(rejected.error.code,'conflict');assert.equal(await a.tracer.evaluations.getOutcome(stale.commandId),null);const closure=await assessmentCommand(a,selection),closed=await w.request(0,'changeAssessments.close',closure,evaluationActor);assert.equal(closed.error.code,'conflict');assert.equal(await a.tracer.evaluations.getOutcome(closure.commandId),null);assert.equal((await a.tracer.changeAssessments.disposition(selection,subject)).actions[0].id,'retained-action');results.push({domain,capability:'assessment',initialAction:initial.actions[0],inputs,disposition,changedBasis:{rejectedCode:rejected.error.code,noOutcome:true,closureRejected:closed.error.code,actionIdentityRetained:true},limits:'Reasoned synthetic fixture action remains open; no completed engineering assessment claimed.'});
 }finally{await w?.close();a.close();}
}
const report={date:'2026-10-28',scope:'Independent OS processes capture competing verification activities, select results versus another capture, and revise the same assessment disposition/action against exact guards. Separate-process criterion changes then reject stale proposals and block unsupported completion. Engineering/research schema bindings use shared contracts.',sourceHashes:['test/verification-fixture.ts','test/application-model-fixture.ts','output/concurrent-local/workload-worker.mjs'].map(path=>({path,sha256:createHash('sha256').update(readFileSync(path)).digest('hex')})),results,limits:'One run per declared scenario/domain. Simultaneous requests, not held-lock instrumentation inside each controlled command; held native-plus-evidence callbacks are separately proven by process crash/backup tests. Synthetic attestations are not human or engineering-domain validation.'};writeFileSync('projects/tracer/concurrent-local-controlled-races.json',await prettier.format(JSON.stringify(report),{...await prettier.resolveConfig('projects/tracer/concurrent-local-controlled-races.json'),parser:'json'}),{flag:'wx'});console.log(JSON.stringify(results.map(r=>({domain:r.domain,capability:r.capability,race:r.capture??r.disposition,changedBasis:r.changedBasis.rejectedCode}))));

