const command=(id)=>({commandId:id,expectedSchemaVersion:7,operations:[{op:'entity.create',input:{type:'@resource',fields:{},resource:{label:'Synthetic HTTP concurrency/recovery probe',source:{system:'file',externalId:id}}}}]});
try{const servers=await Promise.all([open(),open()]),clients=servers.map(s=>createClient({baseUrl:s.origin}));await Promise.all(clients.map(c=>c.connect()));const same=command('same-http-process-command'),outcomes=await Promise.allSettled(clients.map(c=>c.write('/api/changesets',same))),successes=outcomes.filter(x=>x.status==='fulfilled');assert.ok(successes.length>=1);for(const o of outcomes){if(o.status==='fulfilled')assert.deepEqual(o.value,successes[0].value);else assert.equal(o.reason.code,'busy');}const original=await clients[1].read('/api/changeset-outcome',{commandId:same.commandId});assert.deepEqual(original,successes[0].value);
 let posts=0;const lossy=createClient({baseUrl:servers[0].origin,fetch:async(...args)=>{const response=await fetch(...args);if(args[1]?.method==='POST'){posts++;assert.equal(response.status,200);await response.arrayBuffer();throw Error('Dropped committed response deliberately');}return response;}});await lossy.connect();const interrupted=command('lost-http-process-response');await assert.rejects(lossy.write('/api/changesets',interrupted),{code:'outcome_unknown'});assert.equal(posts,1);const inspected=await clients[1].read('/api/changeset-outcome',{commandId:interrupted.commandId});assert.ok(inspected);await stop(servers[0].child);const reopened=await open(),fresh=createClient({baseUrl:reopened.origin});await fresh.connect();assert.deepEqual(await fresh.read('/api/changeset-outcome',{commandId:interrupted.commandId}),inspected);
 const cli=spawnSync(process.execPath,['src/interfaces/cli.ts','--db',database,'--actor','concurrent-http-proof','--reason','Disposable real-project copy only','changeset','outcome',interrupted.commandId],{encoding:'utf8'});assert.equal(cli.status,0,cli.stderr);assert.deepEqual(JSON.parse(cli.stdout),inspected);
