 const page=await fresh.read('/api/configuration-impact',{...pair,limit:1});assert.ok(page.evaluations.nextAfter);const evidenceCommand={commandId:'concurrent-evidence-stales-continuation',expectedSchemaVersion:7,operations:[],receipt:{outputId:'90e3162a-a959-4d3f-95f0-c8c5e9324757',expectedOutputVersion:13,outcome:'Synthetic evidence-only continuation guard probe',inputs:[{entityId:'90e3162a-a959-4d3f-95f0-c8c5e9324757',fields:['statement']}]}};const evidenceResult=await clients[1].write('/api/evaluation-commands',evidenceCommand);assert.ok(evidenceResult.receipt);await assert.rejects(fresh.read('/api/configuration-impact',{...pair,limit:1,after:page.evaluations.nextAfter}),{code:'conflict'});assert.deepEqual(await fresh.read('/api/configuration-comparison',pair),await clients[1].read('/api/configuration-comparison',pair));const afterEvidence=await fresh.read('/api/verification-analysis',selection);assert.deepEqual(afterEvidence.obligations,v.obligations);
 const report={date:'2026-10-28',scope:'Two independent HTTP server OS processes share a disposable online copy of actual Tracer native190/schema7; separate typed clients and a CLI process inspect common durable outcomes. Local trusted-process APIs, not authenticated team clients.',sourceHashes:['output/concurrent-local/http-worker.mjs','src/persistence/sqlite.ts'].map(path=>({path,sha256:createHash('sha256').update(readFileSync(path)).digest('hex')})),sameCommand:same,concurrentOutcomes:outcomes.map(o=>o.status==='fulfilled'?{status:o.status,result:o.value}:{status:o.status,code:o.reason.code}),lostResponseCommand:interrupted,lostResponsePostCount:posts,inspection:inspected,results:{originalOutcomeEqualAcrossServerProcesses:true,oneLostResponseWrite:true,restartedProcessInspectsExactSuccess:true,cliInspectionEqualsHttp:true,fixedPairEqualAcrossProcesses:true,existingCandidateVerification:'verified',staleEvidenceContinuationRejected:true,exactCandidateObligationsUnchangedAfterNewEvidence:true},limitations:'Bounded changeset identity/lost-response task with existing controlled verification inspection. No browser concurrent throughput, controlled disposition/result-selection race, cloud or authentication claim.'};writeFileSync('projects/tracer/concurrent-local-http-recovery-and-cursors.json',await prettier.format(JSON.stringify(report),{...await prettier.resolveConfig('projects/tracer/concurrent-local-http-recovery-and-cursors.json'),parser:'json'}),{flag:'wx'});console.log(JSON.stringify(report.results));
