import{DatabaseSync}from'node:sqlite';import{readFileSync,writeFileSync}from'node:fs';import{createHash}from'node:crypto';import assert from'node:assert/strict';import prettier from'prettier';import{Tracer}from'../../src/index.ts';import{SQLiteRepository}from'../../src/persistence/sqlite.ts';
const originalPrepare=DatabaseSync.prototype.prepare,originalExec=DatabaseSync.prototype.exec;let metrics;
